<div class="page-heading"><div><a class="text-link" href="<?= e(url('classes')) ?>">← Classes</a><h1><?= e($class['name']) ?></h1><p>Class fee: <?= money($class['fee']) ?> · Open a batch to enroll students and collect fees.</p></div><button class="button primary" data-open="batch-dialog">Add batch</button></div>
<div class="cards-grid"><?php foreach($batches as $b): ?><article class="panel class-card"><div class="teacher-top"><span class="badge <?= $b['status']==='Completed'?'neutral':'success' ?>"><?= e($b['status']) ?></span><a class="text-link" href="<?= e(url('classes/'.$class['id'].'/batches?edit='.$b['id'])) ?>">Edit</a></div><h2><?= e($b['name']) ?></h2><p><?= e($b['starts_on']) ?> — <?= e($b['ends_on']?:'No end date') ?></p><p><?= (int)$b['students'] ?> / <?= (int)$b['capacity'] ?> active students</p><a class="panel-bottom" href="<?= e(url('batches/'.$b['id'])) ?>">Open batch <?= icon('arrow') ?></a></article><?php endforeach ?><?php if(!$batches): ?><div class="panel empty wide"><h3>No batches yet.</h3><p>Create the first batch for this class.</p></div><?php endif ?></div>
<dialog id="batch-dialog" <?= $edit || isset($_GET['new']) || !empty($_SESSION['old'])?'data-auto-open':'' ?>><div class="dialog-heading"><h2><?= $edit?'Edit':'Add' ?> batch</h2><button class="icon-button" data-close aria-label="Close">×</button></div><form method="post" action="<?= e(url('learning/batch')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="class_id" value="<?= $class['id'] ?>"><div class="form-grid"><?php input('Batch name','name','text',$edit['name']??''); input('Capacity','capacity','number',$edit['capacity']??$class['capacity']); input('Start date','starts_on','date',$edit['starts_on']??date('Y-m-d')); input('End date','ends_on','date',$edit['ends_on']??'',false); choose('Status','status',['Open'=>'Open','Ongoing'=>'Ongoing','Completed'=>'Completed'],$edit['status']??'Open'); ?></div><div class="form-footer"><button type="button" class="button" data-close>Cancel</button><button class="button primary">Save batch</button></div></form></dialog>
